INSERT INTO `sq_config` (`config_name`, `config_value`, `config_key`, `config_type`, `config_options`, `config_show`, `config_remark`, `config_null_check`, `config_disabled`) VALUES ( '是否启用下载失败歌曲使用其他插件代替下载', 'true', 'system.download.failed.use.other.plugin', 'boolean', '', 1, '如果当前歌曲下载失败，开启后则会根据歌曲名称，专辑，歌手，码率等信息从其他插件中获取下载连接', 1, 0);
INSERT INTO `sq_config` (`config_name`, `config_value`, `config_key`, `config_type`, `config_options`, `config_show`, `config_remark`, `config_null_check`, `config_disabled`) VALUES ( '下载失败时使用其他插件的顺序', 'kw,netease,qqvip,mg,kg', 'system.download.failed.use.other.plugin.order', 'input', '', 1, '下载失败后使用其他插件重新下载的顺序，多个插件用逗号分隔', 1, 0);
INSERT INTO `sq_config` (`config_name`, `config_value`, `config_key`, `config_type`, `config_options`, `config_show`, `config_remark`, `config_null_check`, `config_disabled`) VALUES ( '下载失败时使用其他插件搜索歌曲的匹配模式', 'name_artist_alubm_like', 'system.download.failed.use.other.plugin.match.mode', 'select', '[{\"label\":\"严格匹配（名称+歌手+专辑完全一致）\",\"value\":\"strict\"},{\"label\":\"名称+歌手+专辑包含匹配\",\"value\":\"name_artist_alubm_like\"},{\"label\":\"名称+歌手包含匹配（推荐）\",\"value\":\"name_artist_fuzzy\"},{\"label\":\"仅名称包含匹配（最宽松）\",\"value\":\"name_fuzzy\"}]', 1, 'strict=名称+歌手+专辑完全一致；name_artist_alubm_like=名称+歌手+专辑包含即可；name_artist_fuzzy=名称+歌手包含匹配（推荐）；name_fuzzy=仅名称包含匹配（最宽松）', 1, 0);
